import { createMemo, For, Show, type Component } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";

import { SettlementRecommendationsLayer } from "#base/ui/lenses/layer/settlement-recommendations-layer.js";

import { type PlotTooltipBaseProps } from "./helpers.js";

/** Props for the SettlementRecommendationPlotTooltipContent component */
export type SettlementRecommendationPlotTooltipContentProps = PlotTooltipBaseProps;

/**
 * Determines whether the settlement recommendation tooltip has content to show at the given plot coordinates.
 */
export function hasSettlementRecommendationData(plotCoord: float2): boolean {
	return SettlementRecommendationsLayer.instance.getRecommendationResult(plotCoord.x, plotCoord.y) !== undefined;
}

/**
 * Gets the settlement recommendation result for the given plot coordinates.
 */
export function getSettlementRecommendationData(plotCoord: float2): GetBestSettleLocationsResult | undefined {
	return SettlementRecommendationsLayer.instance.getRecommendationResult(plotCoord.x, plotCoord.y);
}

/**
 * Content component for the settlement recommendation plot tooltip.
 * TODO: Implement the full content rendering.
 */
export const SettlementRecommendationPlotTooltipContent: Component<SettlementRecommendationPlotTooltipContentProps> = (
	props,
) => {
	const recommendation = createMemo(() => getSettlementRecommendationData(props.plotCoord));

	return (
		<Show when={recommendation()}>
			{(data) => (
				<div class="flex flex-row text-accent-2">
					<div class="flex flex-col">
						<For each={data().factors}>
							{(factor) => <span class={factor.positive ? "img-plus-icon" : "img-minus-icon"} />}
						</For>
					</div>
					<div class="flex flex-col justify-around text-sm font-bold mr-5">
						<For each={data().factors}>{(factor) => <L10n.Stylize text={factor.title} />}</For>
					</div>
					<div class="flex flex-col justify-around text-sm">
						<For each={data().factors}>{(factor) => <L10n.Stylize text={factor.description} />}</For>
					</div>
				</div>
			)}
		</Show>
	);
};
